import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p99_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor fused_gelu_softmax_cuda(torch::Tensor x);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_gelu_softmax_cuda", &fused_gelu_softmax_cuda, "Fused GELU+Softmax (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

// Each block processes one row of [rows, cols].
// Block size = 256 threads. cols = 8192 => 32 elements per thread.
// Three passes: (1) apply GELU + find row max, (2) compute exp(v-max) + sum, (3) normalize.
// Uses warp shuffle + shared memory for reductions.

#define BLOCK_SIZE 256

__device__ __forceinline__ float gelu_exact(float v) {
    return 0.5f * v * (1.0f + erff(v * 0.70710678118654752f));
}

__global__ void fused_gelu_softmax_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int rows,
    int cols
) {
    int row = blockIdx.x;
    if (row >= rows) return;

    const float* row_in = input + row * cols;
    float* row_out = output + row * cols;

    int tid = threadIdx.x;
    int nthreads = BLOCK_SIZE;

    // Pass 1: apply GELU to all elements this thread owns, track local max.
    float local_max = -1e30f;
    for (int i = tid; i < cols; i += nthreads) {
        float v = gelu_exact(row_in[i]);
        row_out[i] = v;  // store GELU result
        local_max = fmaxf(local_max, v);
    }

    // Block-wide max reduction using warp shuffles + shared memory.
    __shared__ float smem[32];  // one slot per warp
    int lane = tid & 31;
    int wid  = tid >> 5;

    // Warp-level reduce.
    for (int offset = 16; offset > 0; offset >>= 1)
        local_max = fmaxf(local_max, __shfl_down_sync(0xffffffff, local_max, offset));
    if (lane == 0) smem[wid] = local_max;
    __syncthreads();

    // First warp reduces across warps.
    int nwarps = nthreads >> 5;
    if (wid == 0) {
        float v = (lane < nwarps) ? smem[lane] : -1e30f;
        for (int offset = 16; offset > 0; offset >>= 1)
            v = fmaxf(v, __shfl_down_sync(0xffffffff, v, offset));
        smem[0] = v;
    }
    __syncthreads();
    float row_max = smem[0];

    // Pass 2: compute exp(gelu - max) and accumulate local sum.
    float local_sum = 0.0f;
    for (int i = tid; i < cols; i += nthreads) {
        float e = expf(row_out[i] - row_max);
        row_out[i] = e;
        local_sum += e;
    }

    // Block-wide sum reduction.
    for (int offset = 16; offset > 0; offset >>= 1)
        local_sum += __shfl_down_sync(0xffffffff, local_sum, offset);
    if (lane == 0) smem[wid] = local_sum;
    __syncthreads();

    if (wid == 0) {
        float v = (lane < nwarps) ? smem[lane] : 0.0f;
        for (int offset = 16; offset > 0; offset >>= 1)
            v += __shfl_down_sync(0xffffffff, v, offset);
        smem[0] = v;
    }
    __syncthreads();
    float row_sum = smem[0];
    float inv_sum = 1.0f / row_sum;

    // Pass 3: normalize.
    for (int i = tid; i < cols; i += nthreads) {
        row_out[i] *= inv_sum;
    }
}

torch::Tensor fused_gelu_softmax_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(x.dim() == 2, "Input must be 2D");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");

    int rows = x.size(0);
    int cols = x.size(1);

    auto output = torch::empty_like(x);

    dim3 grid(rows);
    dim3 block(BLOCK_SIZE);

    fused_gelu_softmax_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        rows,
        cols
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a matrix multiplication, applies GELU, and then applies Softmax.
        """
    def __init__(self, in_features, out_features):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.linear = nn.Linear(in_features, out_features)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        x = self.linear(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = _stark_get_extension().fused_gelu_softmax_cuda(x.contiguous())
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        x = x  # softmax is fused into the epilogue kernel above
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        return x
        # <<<END_IMPROVE>>>

