#define WMMA_M 16
#define WMMA_N 16
#define WMMA_K 8

// CTA tile: 4 warps in M direction x 8 warps in N direction = 32 warps = 1024 threads
// Each warp computes one 16x16 output tile
// CTA covers BM=64 rows x BN=128 cols
#define BM 64
#define BN 128
#define BK 16
#define WARPS_M 4
#define WARPS_N 8
#define THREADS_PER_BLOCK 256

__device__ __forceinline__ float gelu_tanh(float v) {
    const float c = 0.7978845608028654f;
    const float a = 0.044715f;
    float t = c * (v + a * v * v * v);
    return 0.5f * v * (1.0f + tanhf(t));
}

