    int warp_row = cta_row + warp_m * WMMA_M;  // global row of this warp's tile
    int warp_col = cta_col + warp_n * WMMA_N;  // global col of this warp's tile

    // Accumulator fragment
    wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float> acc_frag;
    wmma::fill_fragment(acc_frag, 0.0f);

    // Shared memory for A and B tiles
    // A tile: BM x BK, B tile: BN x BK
    __shared__ float smem_A[BM][BK + 4];   // +4 padding to avoid bank conflicts
    __shared__ float smem_B[BN][BK + 4];

    // Loop over K dimension in chunks of BK
    for (int k_base = 0; k_base < K; k_base += BK) {
        // Cooperatively load A tile: BM x BK
