            int total = BM * BK;
            for (int idx = tid; idx < total; idx += THREADS_PER_BLOCK) {
                int r = idx / BK;
                int c = idx % BK;
                int global_row = cta_row + r;
                int global_col = k_base + c;
                smem_A[r][c] = (global_row < M && global_col < K) ? A[global_row * K + global_col] : 0.0f;
            }
        }
        // Cooperatively load B tile: BN x BK
