            int total = BN * BK;
            for (int idx = tid; idx < total; idx += THREADS_PER_BLOCK) {
                int r = idx / BK;
                int c = idx % BK;
                int global_row = cta_col + r;
                int global_col = k_base + c;
                smem_B[r][c] = (global_row < N && global_col < K) ? B[global_row * K + global_col] : 0.0f;
