            for (int off = 16; off > 0; off >>= 1)
                local_max = fmaxf(local_max, __shfl_xor_sync(0xffffffff, local_max, off));

            float local_sum = 0.0f;
            #pragma unroll
            for (int i = 0; i < 4; i++) {
                int col = lane * 4 + i;
                float e = (cta_col + col < N) ? __expf(local_vals[i] - local_max) : 0.0f;
                local_vals[i] = e;
                local_sum += e;
            }
            for (int off = 16; off > 0; off >>= 1)
                local_sum += __shfl_xor_sync(0xffffffff, local_sum, off);

            float inv_sum = 1.0f / local_sum;
            #pragma unroll
            for (int i = 0; i < 4; i++) {
                int col = lane * 4 + i;
                int global_col = cta_col + col;
                if (global_col < N) {
                    C[global_row * N + global_col] = local_vals[i] * inv_sum;
                }
            }
        }
    }
}

