__global__ void fused_gelu_softmax_inplace_kernel(
    float* __restrict__ data,
    int rows,
    int cols
) {
    int row = blockIdx.x;
    if (row >= rows) return;

    float* row_ptr = data + row * cols;
    int tid  = threadIdx.x;
    int lane = tid & 31;
    int wid  = tid >> 5;
    const int nwarps = BLOCK_SIZE >> 5;
    const unsigned warp_mask = (nwarps == 32) ? 0xffffffffu : ((1u << nwarps) - 1u);

    __shared__ float smem[32];

    float local_max = -3.402823466e+38f;

    if ((cols & 3) == 0) {
        float4* row4  = reinterpret_cast<float4*>(row_ptr);
        int ncols4 = cols >> 2;
        for (int i = tid; i < ncols4; i += BLOCK_SIZE) {
            float4 v = row4[i];
            v.x = gelu_fast(v.x);
            v.y = gelu_fast(v.y);
            v.z = gelu_fast(v.z);
            v.w = gelu_fast(v.w);
            row4[i] = v;
            local_max = fmaxf(local_max, fmaxf(fmaxf(v.x, v.y), fmaxf(v.z, v.w)));
        }
    } else {
        for (int i = tid; i < cols; i += BLOCK_SIZE) {
            float v = gelu_fast(row_ptr[i]);
            row_ptr[i] = v;
            local_max = fmaxf(local_max, v);
        }
    }

    for (int off = 16; off > 0; off >>= 1)
        local_max = fmaxf(local_max, __shfl_down_sync(0xffffffff, local_max, off));
    if (lane == 0) smem[wid] = local_max;
    __syncthreads();
    if (tid < nwarps) {
        float v = smem[tid];
        for (int off = nwarps >> 1; off > 0; off >>= 1)
            v = fmaxf(v, __shfl_down_sync(warp_mask, v, off));
        if (tid == 0) smem[0] = v;
    }
    __syncthreads();
    float row_max = smem[0];

    float local_sum = 0.0f;

    if ((cols & 3) == 0) {
        float4* row4  = reinterpret_cast<float4*>(row_ptr);
        int ncols4 = cols >> 2;
        for (int i = tid; i < ncols4; i += BLOCK_SIZE) {
            float4 v = row4[i];
            v.x = __expf(v.x - row_max);
            v.y = __expf(v.y - row_max);
            v.z = __expf(v.z - row_max);
            v.w = __expf(v.w - row_max);
            row4[i] = v;
            local_sum += v.x + v.y + v.z + v.w;
        }
    } else {
        for (int i = tid; i < cols; i += BLOCK_SIZE) {
            float v = __expf(row_ptr[i] - row_max);
            row_ptr[i] = v;
            local_sum += v;
        }
    }

    for (int off = 16; off > 0; off >>= 1)
        local_sum += __shfl_down_sync(0xffffffff, local_sum, off);
    if (lane == 0) smem[wid] = local_sum;
    __syncthreads();
    if (tid < nwarps) {
        float v = smem[tid];
        for (int off = nwarps >> 1; off > 0; off >>= 1)
            v += __shfl_down_sync(warp_mask, v, off);
        if (tid == 0) smem[0] = v;
    }
    __syncthreads();
    float inv_sum = 1.0f / smem[0];

    if ((cols & 3) == 0) {
        float4* row4  = reinterpret_cast<float4*>(row_ptr);
        int ncols4 = cols >> 2;
        for (int i = tid; i < ncols4; i += BLOCK_SIZE) {
            float4 v = row4[i];
            v.x *= inv_sum;
            v.y *= inv_sum;
            v.z *= inv_sum;
            v.w *= inv_sum;
            row4[i] = v;
        }
    } else {
        for (int i = tid; i < cols; i += BLOCK_SIZE) {
            row_ptr[i] *= inv_sum;
        }
    }
}

torch::Tensor fused_gelu_softmax_inplace(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    int rows = x.size(0);
    int cols = x.size(1);
    dim3 grid(rows);
    dim3 block(BLOCK_SIZE);
    fused_gelu_softmax_inplace_kernel<<<grid, block>>>(
        x.data_ptr<float>(), rows, cols
    );
    return x;
}

__global__ void add_bias_kernel(
    float* __restrict__ out,
    const float* __restrict__ bias,
    int rows,
    int cols
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = rows * cols;
    if (idx < total) {
        out[idx] += bias[idx % cols];
    }
}

torch::Tensor linear_tf32(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    TORCH_CHECK(x.is_cuda() && weight.is_cuda() && bias.is_cuda(), "all tensors must be CUDA");
    TORCH_CHECK(x.is_contiguous() && weight.is_contiguous() && bias.is_contiguous(), "all tensors must be contiguous");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(bias.scalar_type() == torch::kFloat32, "bias must be float32");
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(weight.dim() == 2, "weight must be 2D");
    TORCH_CHECK(bias.dim() == 1, "bias must be 1D");

    int M = x.size(0);
    int K = x.size(1);
    int N = weight.size(0);
    TORCH_CHECK(weight.size(1) == K, "weight/x shape mismatch");
    TORCH_CHECK(bias.size(0) == N, "bias/weight shape mismatch");

    auto out = torch::empty({M, N}, x.options());

    cublasHandle_t handle = at::cuda::getCurrentCUDABlasHandle();

    cublasMath_t saved_math_mode;
    cublasGetMathMode(handle, &saved_math_mode);
    cublasSetMathMode(handle, CUBLAS_TF32_TENSOR_OP_MATH);

    float alpha = 1.0f, beta = 0.0f;
    // Row-major C = A * B^T mapped to col-major:
    // C^T (N x M) = weight (N x K) * x^T (K x M)
    // => cublasGemmEx: m=N, n=M, k=K, A=weight(N,K) opA=N lda=K, B=x(M,K) opB=T ldb=K, C=out ldc=N
    cublasStatus_t status = cublasGemmEx(
        handle,
        CUBLAS_OP_T, CUBLAS_OP_N,
        N, M, K,
        &alpha,
        weight.data_ptr<float>(), CUDA_R_32F, K,
        x.data_ptr<float>(),      CUDA_R_32F, K,
        &beta,
        out.data_ptr<float>(),    CUDA_R_32F, N,
        CUBLAS_COMPUTE_32F_FAST_TF32,
        CUBLAS_GEMM_DEFAULT_TENSOR_OP
    );

    cublasSetMathMode(handle, saved_math_mode);
    TORCH_CHECK(status == CUBLAS_STATUS_SUCCESS, "cublasGemmEx failed");

    int total = M * N;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;
    add_bias_kernel<<<blocks, threads>>>(out.data_ptr<float>(), bias.data_ptr<float>(), M, N);

    return out;
}
